SELECT set_config('test.run',public.payroll_run_command('d2401000-0000-4000-8000-000000000001','d2403000-0000-4000-8000-000000000001','d240e000-0000-4000-8000-000000000001',NULL,0,'calculate','rollback binding QA',gen_random_uuid())::text,true);
RESET ROLE;

SELECT ok((SELECT output->'employees'->0->>'employment_id' FROM payroll.candidates WHERE tenant_id='d2401000-0000-4000-8000-000000000001' AND id=(current_setting('test.run')::jsonb->>'candidate_id')::uuid)='d2406000-0000-4000-8000-000000000001','actual candidate uses output employment_id');
SELECT ok(jsonb_array_length(payroll.validate_final_source_currentness('d2401000-0000-4000-8000-000000000001','d2403000-0000-4000-8000-000000000001','d240e000-0000-4000-8000-000000000001',(current_setting('test.run')::jsonb->>'id')::uuid,(current_setting('test.run')::jsonb->>'candidate_id')::uuid))=1,'stored candidate validates one actual current Time dependency');
SELECT is((payroll.validate_final_source_currentness('d2401000-0000-4000-8000-000000000001','d2403000-0000-4000-8000-000000000001','d240e000-0000-4000-8000-000000000001',(current_setting('test.run')::jsonb->>'id')::uuid,(current_setting('test.run')::jsonb->>'candidate_id')::uuid)->0->'identity'->>'fact_id'),'d240c000-0000-4000-8000-000000000001','binding preserves actual fact identity');

-- Explicit non-legal final context/employee fixture: this exercises only the
-- private durable protocol, never readiness or public finalization.
INSERT INTO payroll.approval_events(tenant_id,id,employer_id,run_id,candidate_id,operation,run_revision,actor_id,reason) SELECT tenant_id,'d240f000-0000-4000-8000-000000000001',employer_id,run_id,id,'approve',0,'d2400000-0000-4000-8000-000000000001','nonlegal rollback binding fixture' FROM payroll.candidates WHERE tenant_id='d2401000-0000-4000-8000-000000000001' AND id=(current_setting('test.run')::jsonb->>'candidate_id')::uuid;
