SELECT payroll.insert_final_source_bindings('d2401000-0000-4000-8000-000000000001','d2403000-0000-4000-8000-000000000001','d240e000-0000-4000-8000-000000000001','d2410000-0000-4000-8000-000000000001');
SELECT is((SELECT count(*) FROM payroll.final_source_bindings WHERE tenant_id='d2401000-0000-4000-8000-000000000001' AND output_id='d2410000-0000-4000-8000-000000000001'),1::bigint,'durable binding is inserted for actual output employee');
SELECT payroll.insert_final_source_bindings('d2401000-0000-4000-8000-000000000001','d2403000-0000-4000-8000-000000000001','d240e000-0000-4000-8000-000000000001','d2410000-0000-4000-8000-000000000001');
SELECT is((SELECT count(*) FROM payroll.final_source_bindings WHERE tenant_id='d2401000-0000-4000-8000-000000000001' AND output_id='d2410000-0000-4000-8000-000000000001'),1::bigint,'exact binder replay is a no-op');
