SELECT is(payroll.capture_time_coverage('d2401000-0000-4000-8000-000000000001','d2403000-0000-4000-8000-000000000001','d240e000-0000-4000-8000-000000000001'),jsonb_build_object('contract','cube4-time-coverage-v1','enabled',false,'items','[]'::jsonb),'disabled Time returns canonical empty coverage without source capture');
UPDATE platform_core.tenant_capability_entitlements SET is_granted=true WHERE tenant_id='d2401000-0000-4000-8000-000000000001' AND capability_key='hr.attendance';
SELECT throws_ok($$INSERT INTO payroll.final_source_bindings(tenant_id,output_id,employer_id,period_id,employment_id,source_date,source_domain,source_key,source_identity,source_version,captured_payload,captured_digest,dependency_lineage) SELECT tenant_id,output_id,employer_id,period_id,employment_id,source_date,source_domain,source_key||':conflict',source_identity,source_version,captured_payload,captured_digest,dependency_lineage FROM payroll.final_source_bindings WHERE tenant_id='d2401000-0000-4000-8000-000000000001'$$,'23505',NULL,'same output/date/source identity collision is rejected');
SELECT throws_ok($$UPDATE payroll.final_source_bindings SET captured_payload='{}'::jsonb WHERE tenant_id='d2401000-0000-4000-8000-000000000001'$$,'55000',NULL,'durable binding is immutable');
SELECT ok(has_table_privilege('authenticated','payroll.final_source_bindings','SELECT') IS FALSE AND has_table_privilege('authenticated','payroll.final_source_bindings','INSERT') IS FALSE,'API roles have no direct binding access');
SELECT throws_ok($$SELECT payroll.validate_final_source_currentness('d2401000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000002','d240e000-0000-4000-8000-000000000001',(current_setting('test.run')::jsonb->>'id')::uuid,(current_setting('test.run')::jsonb->>'candidate_id')::uuid)$$,'23514',NULL,'foreign employer scope is rejected');

