SELECT throws_ok($$SELECT payroll.validate_final_source_currentness('d2401000-0000-4000-8000-000000000001','d2403000-0000-4000-8000-000000000001','d240e000-0000-4000-8000-000000000001',(current_setting('test.run')::jsonb->>'id')::uuid,(current_setting('test.run')::jsonb->>'candidate_id')::uuid)$$,'PT409',NULL,'canonical Time fact change makes stored candidate stale');

-- The real append remains blocked by financial/readiness qualification; this
-- also proves no output, receipt, or binding is created on that failure.
SELECT is((SELECT count(*) FROM payroll.final_contexts WHERE tenant_id='d2401000-0000-4000-8000-000000000001'),1::bigint,'only explicit nonlegal fixture output exists before append attempt');
SELECT throws_ok($$SELECT payroll.append_final_output_before_advances('d2401000-0000-4000-8000-000000000001',(current_setting('test.run')::jsonb->>'id')::uuid,(current_setting('test.run')::jsonb->>'candidate_id')::uuid,'d2400000-0000-4000-8000-000000000001',(current_setting('test.run')::jsonb->>'revision')::integer,gen_random_uuid())$$,'23514',NULL,'actual private append remains blocked by approval/readiness');
SELECT is((SELECT count(*) FROM payroll.final_contexts WHERE tenant_id='d2401000-0000-4000-8000-000000000001'),1::bigint,'blocked append creates no additional output');
SELECT * FROM finish();
ROLLBACK;
